Error-handling a timeout
```ts
import { abortable, delay } from "@ende/async";
import { assertRejects, assertEquals } from "@ende/assert";

const promise = delay(1_000);

// Rejects with `DOMException` (name `"TimeoutError"`) after 100 ms
const error = await assertRejects(
  () => abortable(promise, AbortSignal.timeout(100)),
  DOMException,
);
assertEquals(error.name, "TimeoutError");
```

Error-handling an abort
```ts
import { abortable, delay } from "@ende/async";
import { assertRejects, assertEquals } from "@ende/assert";

