Error-handling a timeout
```ts
import { abortable, delay } from "@ende/async";
import { assertRejects, assertEquals } from "@ende/assert";

const asyncIter = async function* () {
  yield "Hello";
  await delay(1_000);
  yield "World";
};

const items: string[] = [];
// Below throws `DOMException` (name `"TimeoutError"`) after 100 ms and items
// become `["Hello"]`
const error = await assertRejects(
  async () => {
    for await (const item of abortable(asyncIter(), AbortSignal.timeout(100))) {
      items.push(item);
    }
  },
  DOMException,
);
assertEquals(error.name, "TimeoutError");
assertEquals(items, ["Hello"]);
```

