With AbortSignal
```ts ignore
import { debounce } from "@ende/async/debounce";

const controller = new AbortController();
const log = debounce(
  (event: Ende.FsEvent) =>
    console.log("[%s] %s", event.kind, event.paths[0]),
  200,
  { signal: controller.signal },
);

for await (const event of Ende.watchFs("./")) {
  log(event);
}

// Abort clears any pending debounce
controller.abort();
```

