Error handling
```ts
import { allSettledKeyed } from "@ende/async/all-keyed";
import { assertEquals, assertExists } from "@ende/assert";

const settled = await allSettledKeyed({
  a: Promise.resolve("ok"),
  b: Promise.reject(new Error("fail")),
