Concurrent deduplication

```ts
import { Lazy } from "@ende/async/lazy";
import { assertEquals } from "@ende/assert";

let initCount = 0;
const config = new Lazy<number>(async () => {
  initCount++;
  return 42;
});

const [a, b] = await Promise.all([config.get(), config.get()]);
assertEquals(a, 42);
assertEquals(b, 42);
assertEquals(initCount, 1);
```

